            (doc_id, doc_revision, doc_revision_attempt,
             "start", "end", last_author, raw_contents,
             acknowledged_revision)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
          RETURNING anchor_id|}
        [
          U.Int64 (A.Doc_id.to_int64 a.doc_id);
          U.Int64 (Int64.of_int a.doc_revision);
          U.Int64 (Int64.of_int a.doc_revision_attempt);
          U.Int64 (Int64.of_int a.range.start);
          U.Int64 (Int64.of_int a.range.end_);
          U.Text (Util.Text.validate_exn (author_to_string a.last_author));
          U.Blob a.raw_contents;
          param_of_int_option a.acknowledged_revision;
        ]
        ~f:(fun stmt ->
          A.Anchor_id.of_int64_exn (Sqlite3.column_int64 stmt 0))
    in
    { a with Internal_types.anchor_id }

  let get db (anchor_id : T.anchor_id) : Internal_types.anchor option =
    U.query_rows db
      (sprintf {|SELECT %s FROM "anchors" WHERE anchor_id = ?|} select_cols)
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]
      ~f:row_to_anchor
    |> function
    | [] -> None
    | x :: _ -> Some x

  let delete db (anchor_id : T.anchor_id) =
    U.exec_params db {|DELETE FROM "anchors" WHERE anchor_id = ?|}
      [ U.Int64 (A.Anchor_id.to_int64 anchor_id) ]

  let relocate db (a : Internal_types.anchor) =
    U.exec_params db
      {|UPDATE "anchors"
        SET doc_id = ?, doc_revision = ?, doc_revision_attempt = ?,
            "start" = ?, "end" = ?, last_author = ?, raw_contents = ?
        WHERE anchor_id = ?|}
      [
        U.Int64 (A.Doc_id.to_int64 a.doc_id);
        U.Int64 (Int64.of_int a.doc_revision);
        U.Int64 (Int64.of_int a.doc_revision_attempt);
        U.Int64 (Int64.of_int a.range.start);
        U.Int64 (Int64.of_int a.range.end_);
        U.Text (Util.Text.validate_exn (author_to_string a.last_author));
        U.Blob a.raw_contents;
        U.Int64 (A.Anchor_id.to_int64 a.anchor_id);
      ]

  let mark_attempt_failed db (anchor_id : T.anchor_id) ~doc_revision_attempt =
    U.exec_params db
      {|UPDATE "anchors" SET doc_revision_attempt = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int doc_revision_attempt);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let acknowledge db (anchor_id : T.anchor_id) ~revision =
    U.exec_params db
      {|UPDATE "anchors" SET acknowledged_revision = ? WHERE anchor_id = ?|}
      [
        U.Int64 (Int64.of_int revision);
        U.Int64 (A.Anchor_id.to_int64 anchor_id);
      ]

  let get_overlapping db (doc_id : T.doc_id) ~start ~end_ :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND "start" < ? AND "end" > ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
        U.Int64 (Int64.of_int end_);
        U.Int64 (Int64.of_int start);
      ]
      ~f:row_to_anchor

  let get_stale db (doc_id : T.doc_id) ~doc_revision :
      Internal_types.anchor list =
    U.query_rows db
      (sprintf
         {|SELECT %s FROM "anchors"
           WHERE doc_id = ? AND doc_revision_attempt < ?|}
         select_cols)
      [
        U.Int64 (A.Doc_id.to_int64 doc_id);
module Documents = struct
  let create_table db =
    U.exec db
      {|
        CREATE TABLE IF NOT EXISTS "documents" (
          doc_id       INTEGER PRIMARY KEY AUTOINCREMENT,
          source_kind  TEXT    NOT NULL,
          source_name  TEXT    NOT NULL,
          locator      TEXT    NOT NULL,
          revision     INTEGER NOT NULL,
          content_hash TEXT,
          contents     BLOB,
          UNIQUE (source_kind, source_name, locator)
        )
      |}

  let param_of_contents = function
    | Active c -> U.Nullable_blob (Some c)
    | Deleted -> U.Nullable_blob None

  (* Column indices, matching this table's own column order above -- every
     row parser below selects them in this same order. *)
  let col_doc_id = 0
  let col_source_kind = 1
  let col_source_name = 2
  let col_locator = 3
  let col_revision = 4
  let col_content_hash = 5
  let col_contents = 6

  let content_hash_of_contents = function
    | Active c -> Some (Digest.to_hex (Digest.string c))
    | Deleted -> None

  let source_params (source : T.source) locator =
    let source_kind, source_name = columns_of_source source in
    [
      U.Text (Util.Text.validate_exn source_kind);
      U.Text (Util.Text.validate_exn source_name);
      U.Text (Util.Text.validate_exn locator);
    ]

  let create db ~(source : T.source) ~locator ~(contents : doc_contents) :
      T.doc_id =
    exec_returning_one db
      {|INSERT INTO "documents"
          (source_kind, source_name, locator, revision, content_hash, contents)
        VALUES (?, ?, ?, 0, ?, ?)
        RETURNING doc_id|}
      (source_params source locator
      @ [
          U.Nullable_text
            (Option.map Util.Text.validate_exn
               (content_hash_of_contents contents));
          param_of_contents contents;
        ])
      ~f:(fun stmt -> A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt 0))

  let create_or_update db ~(source : T.source) ~locator
      ~(contents : doc_contents) : T.doc_id =
    exec_returning_one db
      {|INSERT INTO "documents"
          (source_kind, source_name, locator, revision, content_hash, contents)
        VALUES (?, ?, ?, 0, ?, ?)
        ON CONFLICT (source_kind, source_name, locator) DO UPDATE
          SET revision =
                CASE
                  WHEN content_hash IS NOT excluded.content_hash
                  THEN revision + 1
                  ELSE revision
                END,
              content_hash = excluded.content_hash,
              contents = excluded.contents
        RETURNING doc_id|}
      (source_params source locator
      @ [
          U.Nullable_text
            (Option.map Util.Text.validate_exn
               (content_hash_of_contents contents));
          param_of_contents contents;
        ])
      ~f:(fun stmt -> A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt 0))

  let row_to_doc_meta stmt : T.doc_meta =
    {
      doc_id = A.Doc_id.of_int64_exn (Sqlite3.column_int64 stmt col_doc_id);
      source_doc =
        {
          source =
            source_of_columns
              ( Sqlite3.column_text stmt col_source_kind,
                Sqlite3.column_text stmt col_source_name );
          locator = Sqlite3.column_text stmt col_locator;
        };
      revision = Int64.to_int (Sqlite3.column_int64 stmt col_revision);
      content_hash =
        Sqlite3.column stmt col_content_hash |> Sqlite3.Data.to_string;
    }

  let get_by_id db (doc_id : T.doc_id) : T.doc_meta option =
    U.query_rows db
      {|SELECT doc_id, source_kind, source_name, locator, revision, content_hash
        FROM "documents" WHERE doc_id = ?|}
      [ U.Int64 (A.Doc_id.to_int64 doc_id) ]
      ~f:row_to_doc_meta
    |> function
    | [] -> None
    | x :: _ -> Some x

  let get_by_locator db ~(source : T.source) locator : T.doc_meta option =
    U.query_rows db
      {|SELECT doc_id, source_kind, source_name, locator, revision, content_hash
        FROM "documents"
        WHERE source_kind = ? AND source_name = ? AND locator = ?|}
